-- Translators: Claude (AI-assisted, not yet reviewed by a native speaker), Codex (AI-assisted, not yet reviewed by a native speaker)
local addon_name, addon = ...

local L = LibStub("AceLocale-3.0"):NewLocale(addon_name, "deDE", false, true)
if not L then return end

-- Human translators the About page credits (display names only; the AI is named in the header above).
L[0] = {}

addon.translation = {
-- a600e4ad English: Levels 1–70, every spec. From stealth: Premeditation, then Cheap Shot solo or
--     Garrote in a group, otherwise Ambush (with a dagger in the main hand). In combat: Riposte,
--     Slice and Dice from two combo points (renewed in its last two seconds), Eviscerate on a
--     target about to die, and at five points Rupture when it will last (not while Blade Flurry
--     cleaves), otherwise Eviscerate. Builds with Mutilate or Backstab (dagger) when the target is
--     not attacking you, otherwise Hemorrhage or Sinister Strike. Reminds you of missing poisons,
--     Kick, Blade Flurry and Adrenaline Rush, Cold Blood and Evasion. Expose Armor, Kidney Shot,
--     Feint, Vanish and positioning stay with you.
[1] = "Stufen 1–70, jede Spezialisierung. Aus der Verstohlenheit: Konzentration, dann Fieser Trick solo oder Erdrosseln in einer Gruppe, sonst Hinterhalt (mit einem Dolch in der Waffenhand). Im Kampf: Riposte, Zerhäckseln ab zwei Combopunkten (in seinen letzten zwei Sekunden erneuert), Ausweiden auf ein Ziel kurz vor dem Tod und bei fünf Punkten Blutung, wenn sie voll wirken kann (nicht während Klingenwirbel mehrere Ziele trifft), sonst Ausweiden. Baut mit Verstümmeln oder Meucheln (Dolch) auf, wenn das Ziel Sie nicht angreift, sonst mit Blutsturz oder Finsterem Stoß. Erinnert an fehlende Gifte, Tritt, Klingenwirbel und Adrenalinrausch, Kaltblütigkeit und Entrinnen. Rüstung schwächen, Nierenhieb, Finte, Verschwinden und Positionierung bleiben Ihnen überlassen.",
-- 5f9b3940 English: Melee DPS (Wowhead)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue, The
--     Burning Crusade Classic (variant key: DPS / Wowhead). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[2] = "Nahkampf-DPS (Wowhead)",
-- d6b11787 English: Levels 1–70, every spec, following Wowhead. Same stealth openers, builders and
--     reminders as the simulator version, but Slice and Dice starts from one combo point and every
--     five-point finisher is Eviscerate: no Rupture. Expose Armor, Kidney Shot, Feint, Vanish and
--     positioning stay with you. An alternative to the recommended simulator melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority.
[3] = "Stufen 1–70, jede Spezialisierung, nach Wowhead. Dieselben Eröffner aus der Verstohlenheit, Aufbauangriffe und Erinnerungen wie die Simulation-Version, aber Zerhäckseln beginnt ab einem Combopunkt und jeder Finisher mit fünf Punkten ist Ausweiden: keine Blutung. Rüstung schwächen, Nierenhieb, Finte, Verschwinden und Positionierung bleiben Ihnen überlassen. Eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation nach Simulation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- f8f8f256 English: Melee damage for every Rogue specialization from level 1 to 60, built from Icy
--     Veins, Wowhead and Warcraft Tavern. The builder follows what you know: Mutilate (Sinister
--     Strike for the fifth point), Hemorrhage, Backstab when the target is not facing you, else
--     Sinister Strike. From Stealth it opens with Premeditation, Cheap Shot when solo, Garrote for
--     Subtlety on group elites, else Ambush or Garrote. It keeps Slice and Dice and Venom up, uses
--     Expose Armor in groups on elites when no warrior has five Sunders, then spends five points on
--     Rupture (Subtlety, long fights) or Eviscerate, and never builds past five. Reminders: poisons
--     on each weapon, Kick, Blade Flurry and Adrenaline Rush on packs and elites, Cold Blood,
--     Evasion, Feint, Thistle Tea and Preparation. Left to you: Vanish, Sprint, Kidney Shot, Blind,
--     Sap and positioning. Forever restricts combat data, so Rotation Master lists this premade for
--     reference and does not select it automatically yet.
[4] = "Nahkampfschaden für jede Schurken-Spezialisierung von Stufe 1 bis 60, zusammengestellt aus Icy Veins, Wowhead und Warcraft Tavern. Der Aufbauangriff richtet sich danach, was Sie beherrschen: Verstümmeln (Finsterer Stoß für den fünften Punkt), Blutsturz, Meucheln, wenn das Ziel Ihnen nicht zugewandt ist, sonst Finsterer Stoß. Aus der Verstohlenheit eröffnet sie mit Konzentration, Fieser Trick beim Solospiel, Erdrosseln für Täuschung gegen Elitegegner in der Gruppe, sonst Hinterhalt oder Erdrosseln. Sie hält Zerhäckseln und Toxin aufrecht, nutzt Rüstung schwächen in Gruppen gegen Elitegegner, wenn kein Krieger fünfmal Rüstung zerreißen aufgebracht hat, gibt dann fünf Punkte für Blutung (Täuschung, lange Kämpfe) oder Ausweiden aus und baut nie über fünf Punkte hinaus auf. Erinnerungen: Gifte auf jeder Waffe, Tritt, Klingenwirbel und Adrenalinrausch gegen Gruppen und Elitegegner, Kaltblütigkeit, Entrinnen, Finte, Distelteetee und Vorbereitung. Ihnen überlassen: Verschwinden, Sprinten, Nierenhieb, Blenden, Kopfnuss und Positionierung. Forever schränkt Kampfdaten ein, daher führt Rotation Master diese integrierte Rotation nur zur Referenz auf und wählt sie noch nicht automatisch aus.",
-- 3333c1f0 English: Subtlety, Ambush build (Warcraft Tavern)
[5] = "Täuschung, Hinterhalt-Build (Warcraft Tavern)",
-- 776899da English: Warcraft Tavern's Ambush/Cutthroat Subtlety build: Premeditation and Ambush on
--     every opener, Ambush again whenever Cutthroat allows it, Backstab from behind as the builder
--     (Hemorrhage when the target is facing you), Ghostly Strike on cooldown, and Slice and Dice
--     then Eviscerate at five points with no Rupture. Reminds you to Vanish for another Ambush on a
--     tanked boss. Choose it instead of the recommended Rogue premade if you took the Cutthroat
--     talents; it applies with Subtlety as your main talent tree and Cutthroat talented. Same
--     poison and cooldown reminders as the recommended premade. An alternative to the recommended
--     Rogue DPS premade, off by default: enable it and disable that one, or raise its priority.
[6] = "Täuschungs-Build mit Hinterhalt/Halsabschneider nach Warcraft Tavern: Konzentration und Hinterhalt bei jeder Eröffnung, erneut Hinterhalt, wann immer Halsabschneider es erlaubt, Meucheln von hinten als Aufbauangriff (Blutsturz, wenn das Ziel Ihnen zugewandt ist), Geisterhafter Stoß bei Abklingzeit-Ende sowie Zerhäckseln und dann Ausweiden bei fünf Punkten, ohne Blutung. Erinnert Sie daran, gegen einen getankten Boss für einen weiteren Hinterhalt Verschwinden zu nutzen. Wählen Sie diese statt der empfohlenen integrierten Schurkenrotation, wenn Sie die Halsabschneider-Talente gewählt haben; sie gilt, wenn Täuschung Ihr Haupttalentbaum ist und Halsabschneider als Talent gewählt ist. Dieselben Erinnerungen an Gifte und Abklingzeiten wie die empfohlene integrierte Rotation. Eine Alternative zur empfohlenen integrierten Schurken-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- 208fc263 English: Subtlety, Garrote build (Wowhead)
[7] = "Täuschung, Erdrosseln-Build (Wowhead)",
-- 919f756d English: Wowhead's Subtlety: Premeditation and Garrote on every opener, and Vanish (then
--     Preparation) used in the rotation to open with Garrote again once the last one has run out.
--     Slice and Dice kept up, Expose Armor in groups, Rupture as the five-point finisher,
--     Hemorrhage as the only builder. This spends Vanish, your escape, on damage: choose it
--     deliberately. It applies with Subtlety as your main talent tree, Dirty Deeds talented and
--     Premeditation known. Same poison and cooldown reminders as the recommended premade. An
--     alternative to the recommended Rogue DPS premade, off by default: enable it and disable that
--     one, or raise its priority.
[8] = "Täuschung nach Wowhead: Konzentration und Erdrosseln bei jeder Eröffnung, und Verschwinden (danach Vorbereitung) wird in der Rotation genutzt, um erneut mit Erdrosseln zu eröffnen, sobald das letzte ausgelaufen ist. Zerhäckseln wird aufrechterhalten, Rüstung schwächen in Gruppen, Blutung als Finisher mit fünf Punkten, Blutsturz als einziger Aufbauangriff. Dies verbraucht Verschwinden, Ihre Fluchtmöglichkeit, für Schaden: Wählen Sie es bewusst. Es gilt, wenn Täuschung Ihr Haupttalentbaum ist, Schmutzige Tricks als Talent gewählt ist und Konzentration bekannt ist. Dieselben Erinnerungen an Gifte und Abklingzeiten wie die empfohlene integrierte Rotation. Eine Alternative zur empfohlenen integrierten Schurken-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität.",
-- ea331596 English: Recommended for Assassination in Midnight. In combat the game now hides your
--     bleeds, buffs, energy, cooldown times and health from addons, so this shows Blizzard's own
--     Assisted Combat suggestion (the one-button rotation, which handles the stealth opener,
--     Garrote, Rupture, Envenom, Deathmark and Kingsbane), and stops while you cast or have no
--     enemy targeted. Reminders for what it leaves out: a lethal and a non-lethal poison and
--     Stealth between pulls, Vanish when you are out of stealth in combat, Kick on an interruptible
--     cast (it lights only where the game lets the cast be read). Health is hidden on Retail, so
--     Crimson Vial is your call.
[9] = "Empfohlen für Meucheln in Midnight. Im Kampf verbirgt das Spiel nun Ihre Blutungen, Stärkungszauber, Energie, Abklingzeiten und Gesundheit vor Addons, daher zeigt diese Rotation den eigenen Vorschlag von Blizzards Kampfassistent (die Ein-Tasten-Rotation, die den Eröffner aus der Verstohlenheit, Erdrosseln, Blutung, Vergiften, Todesmal und Königsmord übernimmt) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: ein tödliches und ein nicht tödliches Gift sowie Verstohlenheit zwischen den Kämpfen, Verschwinden, wenn Sie im Kampf nicht in Verstohlenheit sind, Tritt bei einem unterbrechbaren Zauber (er leuchtet nur dort auf, wo das Spiel den Zauber auslesen lässt). Die Gesundheit ist unter Retail verborgen, daher bleibt Blutrote Phiole Ihnen überlassen.",
-- 04026a9b English: Reference only, off by default: the Icy Veins and SimulationCraft order keeps
--     bleeds up by their timers, which Midnight hides in combat; energy is hidden on Retail, so its
--     energy pooling is left out. From stealth Garrote, then Ambush. Garrote in its last 30% while
--     you are not at full combo points, Rupture at 5+ in its last 30%; at 5+ combo points Coup de
--     Grace or Envenom; below, Crimson Tempest on three or more enemies, Fan of Knives on two or
--     more close by, Ambush, Mutilate. Reminders: Deathmark with both bleeds up, Kingsbane
--     alongside it, Vanish with Deathmark ready, Shiv on a Deathstalker's Mark target, Thistle Tea
--     whenever it is ready in combat, plus the shared poison, Stealth and Kick reminders.
[10] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft hält Blutungen anhand ihrer Timer aufrecht, die Midnight im Kampf verbirgt; Energie ist unter Retail verborgen, daher entfällt das Ansammeln von Energie. Aus der Verstohlenheit Erdrosseln, dann Hinterhalt. Erdrosseln in seinen letzten 30 %, solange Sie nicht die vollen Combopunkte haben, Blutung bei 5+ in ihren letzten 30 %; bei 5+ Combopunkten Gnadenstoß oder Vergiften; darunter Blutroter Sturm gegen drei oder mehr Gegner, Dolchfächer gegen zwei oder mehr in der Nähe, Hinterhalt, Verstümmeln. Erinnerungen: Todesmal bei beiden aktiven Blutungen, Königsmord zusammen damit, Verschwinden bei bereitem Todesmal, Tückische Klinge auf ein Ziel mit Mal des Todespirschers, Disteltee, wann immer er im Kampf bereit ist, dazu die gemeinsamen Erinnerungen an Gifte, Verstohlenheit und Tritt.",
-- bb9cc61b English: Recommended for Outlaw in Midnight. Shows Blizzard's Assisted Combat suggestion
--     (it handles the stealth opener, Roll the Bones, Blade Flurry, Adrenaline Rush, Between the
--     Eyes and the finishers), and stops while you cast or have no enemy targeted. Reminders for
--     what it leaves out: poisons and Stealth between pulls, Vanish when you are out of stealth in
--     combat, Kick. Health is hidden on Retail, so Crimson Vial is your call. Keep It Rolling stays
--     with you: the game hides how many Roll the Bones buffs you have.
[11] = "Empfohlen für Gesetzlosigkeit in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (er übernimmt den Eröffner aus der Verstohlenheit, Schicksalswürfel, Klingenwirbel, Adrenalinrausch, Zwischen die Augen und die Finisher) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Gifte und Verstohlenheit zwischen den Kämpfen, Verschwinden, wenn Sie im Kampf nicht in Verstohlenheit sind, Tritt. Die Gesundheit ist unter Retail verborgen, daher bleibt Blutrote Phiole Ihnen überlassen. Großer Wurf bleibt Ihnen überlassen: Das Spiel verbirgt, wie viele Stärkungszauber von Schicksalswürfel Sie haben.",
-- 3a3eecef English: Reference only, off by default: the Icy Veins, SimulationCraft and Wowhead
--     order reads Roll the Bones buffs, Opportunity stacks and energy, which Midnight hides in
--     combat. From stealth Ambush. One combo point short of full or more: Between the Eyes, Killing
--     Spree, Coup de Grace, Dispatch. Otherwise Ambush with Audacity, Pistol Shot at six
--     Opportunity stacks (three when low on combo points), Ambush, Sinister Strike. Reminders: Roll
--     the Bones with no roll up, Adrenaline Rush at two or fewer combo points, Blade Flurry kept up
--     on two or more enemies, Blade Rush, Preparation when Adrenaline Rush, Between the Eyes and
--     Blade Rush are all cooling. Keep It Rolling stays manual.
[12] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins, SimulationCraft und Wowhead liest die Stärkungszauber von Schicksalswürfel, Stapel von Gelegenheit und Energie, die Midnight im Kampf verbirgt. Aus der Verstohlenheit Hinterhalt. Ab einem Combopunkt unter dem Maximum: Zwischen die Augen, Mordlust, Gnadenstoß, Tötung. Sonst Hinterhalt mit Unverfroren, Pistolenschuss bei sechs Stapeln Gelegenheit (drei bei wenigen Combopunkten), Hinterhalt, Finsterer Stoß. Erinnerungen: Schicksalswürfel ohne aktiven Wurf, Adrenalinrausch bei zwei oder weniger Combopunkten, Klingenwirbel gegen zwei oder mehr Gegner aufrechterhalten, Klingenansturm, Vorbereitung, wenn Adrenalinrausch, Zwischen die Augen und Klingenansturm alle abklingen. Großer Wurf bleibt manuell.",
-- 96f6f8ea English: Recommended for Subtlety in Midnight. Shows Blizzard's Assisted Combat
--     suggestion (it handles the stealth opener, Shadow Blades, Goremaw's Bite, Shadow Dance,
--     Secret Technique and the finishers), and stops while you cast or have no enemy targeted.
--     Reminders for what it leaves out: poisons and Stealth between pulls, Kick on an interruptible
--     cast. Health is hidden on Retail, so Crimson Vial is your call.
[13] = "Empfohlen für Täuschung in Midnight. Zeigt den Vorschlag von Blizzards Kampfassistent (er übernimmt den Eröffner aus der Verstohlenheit, Schattenklingen, Blutschlunds Biss, Schattentanz, Geheimtechnik und die Finisher) und pausiert, während Sie wirken oder kein Gegner anvisiert ist. Erinnerungen an das, was er auslässt: Gifte und Verstohlenheit zwischen den Kämpfen, Tritt bei einem unterbrechbaren Zauber. Die Gesundheit ist unter Retail verborgen, daher bleibt Blutrote Phiole Ihnen überlassen.",
-- 5fff6443 English: Reference only, off by default: the Icy Veins and SimulationCraft order holds
--     Shadow Dance for Secret Technique and reads Shadow Dance, Darkest Night and energy, which
--     Midnight hides in combat. Stealthed before the pull: Shadowstrike. One combo point short of
--     full or more: Eviscerate with Darkest Night, Secret Technique in Shadow Dance, Coup de Grace,
--     Black Powder on three or more enemies, Eviscerate. Otherwise Shadowstrike, Shuriken Storm on
--     two or more, Gloomblade or Backstab. Reminders: Goremaw's Bite in Shadow Dance, Shadow Blades
--     with Shadow Dance ready, Shadow Dance at two or fewer (or six or more) combo points when
--     Secret Technique is ready or Shadow Blades is up, Vanish out of stealth at two or fewer combo
--     points.
[14] = "Nur als Referenz, standardmäßig deaktiviert: die Reihenfolge von Icy Veins und SimulationCraft hält Schattentanz für Geheimtechnik zurück und liest Schattentanz, Dunkelste Nacht und Energie, die Midnight im Kampf verbirgt. In Verstohlenheit vor dem Pull: Schattenschlag. Ab einem Combopunkt unter dem Maximum: Ausweiden mit Dunkelster Nacht, Geheimtechnik während Schattentanz, Gnadenstoß, Schwarzpulver gegen drei oder mehr Gegner, Ausweiden. Sonst Schattenschlag, Shurikensturm gegen zwei oder mehr, Düstere Klinge oder Meucheln. Erinnerungen: Blutschlunds Biss während Schattentanz, Schattenklingen bei bereitem Schattentanz, Schattentanz bei zwei oder weniger (oder sechs oder mehr) Combopunkten, wenn Geheimtechnik bereit oder Schattenklingen aktiv ist, Verschwinden außerhalb der Verstohlenheit bei zwei oder weniger Combopunkten.",
-- 797e018d English: Recommended before you choose a specialization (while the game reports the
--     Rogue's initial specialization). Highlights the spell Blizzard's Assisted Combat suggests
--     next, the one rotation advice the game still lets an addon read in Midnight combat; it waits
--     while you cast or channel. Alongside it, the reminders every Rogue premade shares, each once
--     you know its spell. When you choose a specialization at level 10, that specialization's
--     premades take over.
[15] = "Empfohlen, bevor Sie eine Spezialisierung wählen (solange das Spiel die Anfangsspezialisierung des Schurken meldet). Hebt den Zauber hervor, den Blizzards Kampfassistent als Nächstes vorschlägt, den einzigen Rotationshinweis, den das Spiel ein Addon im Kampf in Midnight noch auslesen lässt; sie wartet, während Sie wirken oder kanalisieren. Daneben die Erinnerungen, die jede integrierte Schurke-Rotation teilt, jeweils sobald Sie den Zauber kennen. Wenn Sie auf Stufe 10 eine Spezialisierung wählen, übernehmen die integrierten Rotationen dieser Spezialisierung.",
-- 5fc6d26a English: Levels 1–60, every spec, also on Hardcore and Self-Found realms; built from
--     simulator, Icy Veins and Wowhead. From Stealth: Premeditation, Ambush with a dagger when the
--     target is not facing you, Cheap Shot solo, Garrote outside raids. In combat: Riposte, Slice
--     and Dice from one combo point when it is missing on an elite or a healthy target (renewed at
--     five points in its last three seconds), Expose Armor at five points in a group when you have
--     Improved Expose Armor 2/2 and nobody Sunders, a two-point Eviscerate on a target about to
--     die, otherwise Eviscerate at five and no builder past five. The builder follows what you
--     know: Ghostly Strike and Hemorrhage outside raids, Backstab with a dagger when the target is
--     not facing you, else Sinister Strike. Reminders: poisons on each weapon (Deadly on an
--     off-hand weapon when carried), Kick, Thistle Tea, Blade Flurry and Adrenaline Rush on elites
--     or two enemies with Slice and Dice up, Cold Blood at five, Evasion solo when hurt. Vanish,
--     Gouge, Preparation, Kidney Shot and racials are listed off; Feint, Sprint, Blind, Sap and
--     positioning stay with you.
[16] = "Stufen 1–60, jede Spezialisierung, auch auf Hardcore- und Self-Found-Realms; zusammengestellt aus Simulation, Icy Veins und Wowhead. Aus der Verstohlenheit: Konzentration, Hinterhalt mit einem Dolch, wenn das Ziel Ihnen nicht zugewandt ist, Fieser Trick solo, Erdrosseln außerhalb von Schlachtzügen. Im Kampf: Riposte, Zerhäckseln ab einem Combopunkt, wenn es auf einem Elitegegner oder einem Ziel mit viel Gesundheit fehlt (bei fünf Punkten in seinen letzten drei Sekunden erneuert), Rüstung schwächen bei fünf Punkten in einer Gruppe, wenn Sie Verbessertes Rüstung schwächen 2/2 haben und niemand Rüstung zerreißen nutzt, Ausweiden mit zwei Punkten auf ein Ziel kurz vor dem Tod, sonst Ausweiden bei fünf und kein Aufbauangriff über fünf hinaus. Der Aufbauangriff richtet sich danach, was Sie beherrschen: Geisterhafter Stoß und Blutsturz außerhalb von Schlachtzügen, Meucheln mit einem Dolch, wenn das Ziel Ihnen nicht zugewandt ist, sonst Finsterer Stoß. Erinnerungen: Gifte auf jeder Waffe (Tödliches Gift auf einer Schildhandwaffe, wenn vorhanden), Tritt, Disteltee, Klingenwirbel und Adrenalinrausch gegen Elitegegner oder zwei Gegner bei aktivem Zerhäckseln, Kaltblütigkeit bei fünf Punkten, Entrinnen solo bei Verletzung. Verschwinden, Solarplexus, Vorbereitung, Nierenhieb und Volksfähigkeiten sind als deaktivierte Schritte aufgeführt; Finte, Sprinten, Blenden, Kopfnuss und Positionierung bleiben Ihnen überlassen.",
-- 64659ecb English: Melee DPS, five-point finishers (Warcraft Tavern)
[17] = "Nahkampf-DPS, Finisher mit fünf Punkten (Warcraft Tavern)",
-- 6e2089d2 English: Warcraft Tavern's way, an alternative to the recommended melee DPS premade, off
--     by default: enable it and disable that one, or raise its priority. Every finisher waits for
--     five combo points so Relentless Strikes refunds it. Slice and Dice is used from its second
--     rank (level 42) when missing or ending, otherwise Eviscerate; no low-point Slice, no
--     near-death Eviscerate and no Expose Armor (a warrior's Sunder covers it). Same openers,
--     builders and reminders as the recommended premade.
[18] = "Die Spielweise von Warcraft Tavern, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Jeder Finisher wartet auf fünf Combopunkte, damit Unerbittliche Stöße ihn zurückerstattet. Zerhäckseln wird ab seinem zweiten Rang (Stufe 42) genutzt, wenn es fehlt oder ausläuft, sonst Ausweiden; kein Zerhäckseln mit wenigen Punkten, kein Ausweiden kurz vor dem Tod des Ziels und kein Rüstung schwächen (Rüstung zerreißen eines Kriegers deckt das ab). Dieselben Eröffner, Aufbauangriffe und Erinnerungen wie die empfohlene integrierte Rotation.",
-- 1bddd98c English: Swords, swing-synced Sinister Strike (simulator)
[19] = "Schwerter, Finsterer Stoß im Schlagtakt (Simulation)",
-- a0a38e03 English: The simulator "sweaty" Combat order for Sword Specialization, an alternative to
--     the recommended melee DPS premade, off by default: enable it and disable that one, or raise
--     its priority. Sinister Strike only right after a main-hand swing (2.0 seconds or more to the
--     next one, set for a 2.6–2.8 speed sword; change it in a clone), unless energy is near full or
--     the target is about to die, so the extra sword attack does not delay your swing. Eviscerate
--     at five also waits for Slice and Dice, full energy or a dying target. Otherwise as the
--     recommended premade.
[20] = "Die „schweißtreibende“ Kampf-Reihenfolge von Simulation für Schwert-Spezialisierung, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Finsterer Stoß nur direkt nach einem Schlag der Waffenhand (2,0 Sekunden oder mehr bis zum nächsten, eingestellt für ein Schwert mit Geschwindigkeit 2,6–2,8; ändern Sie es in einer Kopie), außer die Energie ist fast voll oder das Ziel stirbt gleich, damit der zusätzliche Schwertangriff Ihren Schlag nicht verzögert. Ausweiden bei fünf Punkten wartet außerdem auf Zerhäckseln, volle Energie oder ein sterbendes Ziel. Ansonsten wie die empfohlene integrierte Rotation.",
-- 1b2af050 English: Season of Discovery, levels 1–60 with runes as you engrave them; built from
--     simulator Phase 6, Icy Veins and Zockify Phase 8. From Stealth: Shadowstrike, Garrote in a
--     group, Ambush for a Backstab build with a dagger, Cheap Shot solo. On three or more enemies
--     fighting you: Blunderbuss, Crimson Tempest, Fan of Knives first. Then Ambush on a Cutthroat
--     proc (with a dagger), Saber Slash kept at three stacks, Poisoned Knife at four poison stacks,
--     Slice and Dice from two points (renewed from four, unless Cut to the Chase is engraved),
--     Expose Armor duty when nobody Sunders or keeps Sebacious Poison up, with Carnage engraved a
--     bleed (Crimson Tempest, else Rupture; none with Saber Slash), Envenom at five (Eviscerate
--     until you engrave it), and a builder by glove rune: Mutilate, Saber Slash, Backstab (with a
--     dagger), else Sinister Strike. Reminders: a temporary enchant on each weapon, Kick, Thistle
--     Tea, Blade Flurry, Adrenaline Rush, Cold Blood and Evasion, and with Master of Subtlety
--     engraved Vanish to renew it and Preparation.
[21] = "Saison der Entdeckungen, Stufen 1–60 mit Runen, sobald Sie sie gravieren; zusammengestellt aus Simulation Phase 6, Icy Veins und Zockify Phase 8. Aus der Verstohlenheit: Schattenschlag, Erdrosseln in einer Gruppe, Hinterhalt für einen Meucheln-Build mit einem Dolch, Fieser Trick solo. Wenn drei oder mehr Gegner gegen Sie kämpfen: zuerst Donnerbüchse, Blutroter Sturm, Dolchfächer. Dann Hinterhalt bei einem Proc von Halsabschneider (mit einem Dolch), Säbelschlitzer bei drei Stapeln gehalten, Vergiftetes Messer bei vier Giftstapeln, Zerhäckseln ab zwei Punkten (ab vier erneuert, außer mit eingravierter Rune „Cut to the Chase“), Rüstung schwächen übernehmen, wenn niemand Rüstung zerreißen nutzt oder Zähes Gift aufrechterhält, mit eingravierter Rune Massaker eine Blutung (Blutroter Sturm, sonst Blutung; keine mit Säbelschlitzer), Vergiften bei fünf Punkten (Ausweiden, bis Sie es gravieren) und ein Aufbauangriff je nach Handschuhrune: Verstümmeln, Säbelschlitzer, Meucheln (mit einem Dolch), sonst Finsterer Stoß. Erinnerungen: eine temporäre Verzauberung auf jeder Waffe, Tritt, Disteltee, Klingenwirbel, Adrenalinrausch, Kaltblütigkeit und Entrinnen sowie mit eingravierter Rune Meister des hinterhältigen Angriffs Verschwinden, um sie zu erneuern, und Vorbereitung.",
-- e2dafa09 English: Melee DPS, Rupture for Carnage (SoD, Icy Veins)
[22] = "Nahkampf-DPS, Blutung für Massaker (SoD, Icy Veins)",
-- 9aaebdaf English: Icy Veins' Season of Discovery order, an alternative to the recommended Season
--     of Discovery melee DPS premade, off by default: enable it and disable that one, or raise its
--     priority. Every finisher at five combo points, first Slice and Dice when missing or ending,
--     then Rupture kept up when Carnage is engraved, then Envenom; Poisoned Knife only at five
--     poison stacks; Blunderbuss or Fan of Knives on three enemies. Same openers, builders and
--     reminders as the recommended premade; Sebacious Poison duty stays with you.
[23] = "Die Reihenfolge von Icy Veins für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Jeder Finisher bei fünf Combopunkten, zuerst Zerhäckseln, wenn es fehlt oder ausläuft, dann Blutung aufrechterhalten, wenn Massaker eingraviert ist, dann Vergiften; Vergiftetes Messer nur bei fünf Giftstapeln; Donnerbüchse oder Dolchfächer gegen drei Gegner. Dieselben Eröffner, Aufbauangriffe und Erinnerungen wie die empfohlene integrierte Rotation; das Aufrechterhalten von Zähes Gift bleibt Ihnen überlassen.",
-- 0a82bcd6 English: Melee DPS, lean Envenom (SoD, Zockify)
[24] = "Nahkampf-DPS, schlankes Vergiften (SoD, Zockify)",
-- b718caf6 English: Zockify's lean Season of Discovery list, an alternative to the recommended
--     Season of Discovery melee DPS premade, off by default: enable it and disable that one, or
--     raise its priority. No bleeds and no Expose Armor. Poisoned Knife at four poison stacks,
--     Slice and Dice when missing (from two points, four with Saber Slash), Envenom at five, then
--     the glove-rune builder. The Vanish and Cold Blood burst stays with you.
[25] = "Die schlanke Liste von Zockify für die Saison der Entdeckungen, eine Alternative zur empfohlenen integrierten Nahkampf-DPS-Rotation der Saison der Entdeckungen, standardmäßig deaktiviert: Aktivieren Sie sie und deaktivieren Sie die empfohlene, oder erhöhen Sie ihre Priorität. Keine Blutungen und kein Rüstung schwächen. Vergiftetes Messer bei vier Giftstapeln, Zerhäckseln, wenn es fehlt (ab zwei Punkten, mit Säbelschlitzer ab vier), Vergiften bei fünf Punkten, dann der Aufbauangriff der Handschuhrune. Der Burst mit Verschwinden und Kaltblütigkeit bleibt Ihnen überlassen.",
-- a76bbe4d English: Season of Discovery tank, chosen when Just a Flesh Wound is engraved; built
--     from simulator Phase 6, Icy Veins, Zockify and Warcraft Tavern. Riposte, Main Gauche on
--     cooldown, Blade Dance from one combo point (renewed from three), Slice and Dice from three
--     (renewed from four), Fan of Knives, Crimson Tempest and Blunderbuss on three or more enemies,
--     Blunderbuss while Blade Dance is up, Eviscerate at five with both buffs up, Poisoned Knife at
--     low energy, then Saber Slash, Mutilate or Sinister Strike. Reminders: Tease in a group when
--     your target attacks someone else, Kick, Evasion below half health, Blade Flurry, Adrenaline
--     Rush, Thistle Tea and weapon poisons (the off-hand one only with an off-hand weapon).
--     Shadowstep and Sebacious Poison duty stay with you.
[26] = "Tank in der Saison der Entdeckungen, gewählt, wenn Nur eine Fleischwunde graviert ist; zusammengestellt aus Simulation Phase 6, Icy Veins, Zockify und Warcraft Tavern. Riposte, Parierdolch bei Abklingzeit-Ende, Klingentanz ab einem Combopunkt (ab drei erneuert), Zerhäckseln ab drei (ab vier erneuert), Dolchfächer, Blutroter Sturm und Donnerbüchse gegen drei oder mehr Gegner, Donnerbüchse, solange Klingentanz aktiv ist, Ausweiden bei fünf Punkten, wenn beide Stärkungszauber aktiv sind, Vergiftetes Messer bei wenig Energie, dann Säbelschlitzer, Verstümmeln oder Finsterer Stoß. Erinnerungen: Reizen in einer Gruppe, wenn Ihr Ziel jemand anderen angreift, Tritt, Entrinnen unter halber Gesundheit, Klingenwirbel, Adrenalinrausch, Disteltee und Waffengifte (das der Schildhand nur mit einer Schildhandwaffe). Schattenschritt und das Aufrechterhalten von Zähes Gift bleiben Ihnen überlassen.",
-- a78d028d English: Recommended for Assassination, from level 10 to 90 (simulator and Wowhead for
--     Phase 5, with Icy Veins' leveling steps). Opens from Stealth with Cheap Shot when solo,
--     otherwise Mutilate (Dispatch on Blindside, with a dagger). Keeps Slice and Dice up (Envenom
--     refreshes it from level 60) and Rupture on the target, spends five points on Envenom while
--     Rupture lasts and four points to keep the Envenom buff rolling when you do not have
--     Anticipation, then Marked for Death, Dispatch below 35% or on Blindside (it needs a dagger in
--     the main hand), and Mutilate. Against four or more enemies fighting you: Slice and Dice,
--     Crimson Tempest at seven, Rupture, Envenom and Fan of Knives; tabbing Rupture onto other
--     targets is up to you. Solo it adds Recuperate and a Kidney Shot when you are low. Reminders:
--     poisons, Kick, Vendetta on long fights, Shadow Blades with Vendetta, Vanish and Preparation
--     inside Vendetta, Shadowstep from range, Evasion solo. Left to you: Tricks of the Trade and
--     Expose Armor (listed but off), Feint, Sprint and positioning.
[27] = "Empfohlen für Meucheln von Stufe 10 bis 90 (Simulation und Wowhead für Phase 5, mit den Leveling-Schritten von Icy Veins). Eröffnet aus der Verstohlenheit solo mit Fieser Trick, sonst mit Verstümmeln (Tötung bei Überrumpeln, mit einem Dolch). Hält Zerhäckseln aufrecht (ab Stufe 60 erneuert Vergiften es) und Blutung auf dem Ziel, gibt fünf Punkte für Vergiften aus, solange Blutung anhält, und vier Punkte, um den Stärkungszauber von Vergiften am Laufen zu halten, wenn Sie Erwartung nicht haben, dann Todesurteil, Tötung unter 35 % oder bei Überrumpeln (dafür ist ein Dolch in der Waffenhand nötig) und Verstümmeln. Wenn vier oder mehr Gegner gegen Sie kämpfen: Zerhäckseln, Blutroter Sturm bei sieben, Blutung, Vergiften und Dolchfächer; Blutung per Tab-Wechsel auf andere Ziele zu verteilen bleibt Ihnen überlassen. Solo kommen Gesundung und ein Nierenhieb bei niedriger Gesundheit hinzu. Erinnerungen: Gifte, Tritt, Vendetta bei langen Kämpfen, Schattenklingen mit Vendetta, Verschwinden und Vorbereitung während Vendetta, Schattenschritt aus der Distanz, Entrinnen solo. Ihnen überlassen: Schurkenhandel und Rüstung schwächen (aufgeführt, aber deaktiviert), Finte, Sprinten und Positionierung.",
-- 446abf99 English: Envenom at five (Icy Veins)
[28] = "Vergiften bei fünf Punkten (Icy Veins)",
-- 584543ab English: Off by default. The Icy Veins and Method order: Vanish on cooldown for a
--     stealthed Mutilate, Vendetta on cooldown when the fight is long enough, Envenom only at five
--     points, Rupture kept up, Dispatch below 35% or on Blindside, Mutilate. Four to eight enemies:
--     Fan of Knives with Rupture at three points or more; nine or more: Fan of Knives and Envenom
--     only. The recommended Assassination premade follows the newer Phase 5 advice instead; to use
--     this one, enable it and disable the recommended one.
[29] = "Standardmäßig deaktiviert. Die Reihenfolge von Icy Veins und Method: Verschwinden bei Abklingzeit-Ende für ein Verstümmeln aus der Verstohlenheit, Vendetta bei Abklingzeit-Ende, wenn der Kampf lang genug ist, Vergiften nur bei fünf Punkten, Blutung aufrechterhalten, Tötung unter 35 % oder bei Überrumpeln, Verstümmeln. Vier bis acht Gegner: Dolchfächer mit Blutung ab drei Punkten; neun oder mehr: nur Dolchfächer und Vergiften. Die empfohlene integrierte Meucheln-Rotation folgt stattdessen den neueren Empfehlungen für Phase 5; um diese zu verwenden, aktivieren Sie sie und deaktivieren Sie die empfohlene.",
-- e298e91f English: Recommended for Combat, from level 10 to 90 (Wowhead and simulator for Phase
--     5). Since the Siege of Orgrimmar patch Sinister Strike costs 50 energy, so Revealing Strike
--     is the builder and Sinister Strike is used only under Bloodlust or Heroism with Adrenaline
--     Rush (and before level 20). Opens with Cheap Shot solo, otherwise Ambush. Keeps Slice and
--     Dice up from two points and Revealing Strike on the target, spends five points only while
--     Revealing Strike is up (Slice and Dice, Rupture on a long single-target fight without Blade
--     Flurry, Eviscerate) and waits for energy at five. Against eight or more enemies: Slice and
--     Dice, Crimson Tempest and Fan of Knives. Solo it adds Recuperate and Kidney Shot. Reminders:
--     poisons, Kick, Blade Flurry on against two or more enemies and off again, Adrenaline Rush at
--     low energy with Shadow Blades, Killing Spree, Vanish and Preparation for Ambush in Deep
--     Insight, Shadowstep, Evasion solo. Left to you: Tricks of the Trade and Expose Armor (listed
--     but off), Feint and positioning behind the target for Ambush.
[30] = "Empfohlen für Kampf von Stufe 10 bis 90 (Wowhead und Simulation für Phase 5). Seit dem Patch zur Schlacht um Orgrimmar kostet Finsterer Stoß 50 Energie, daher ist Enthüllender Stoß der Aufbauangriff, und Finsterer Stoß wird nur während Kampfrausch oder Heldentum mit Adrenalinrausch (und vor Stufe 20) genutzt. Eröffnet solo mit Fieser Trick, sonst mit Hinterhalt. Hält Zerhäckseln ab zwei Punkten aufrecht und Enthüllender Stoß auf dem Ziel, gibt fünf Punkte nur aus, solange Enthüllender Stoß aktiv ist (Zerhäckseln, Blutung bei einem langen Einzelzielkampf ohne Klingenwirbel, Ausweiden), und wartet bei fünf Punkten auf Energie. Gegen acht oder mehr Gegner: Zerhäckseln, Blutroter Sturm und Dolchfächer. Solo kommen Gesundung und Nierenhieb hinzu. Erinnerungen: Gifte, Tritt, Klingenwirbel gegen zwei oder mehr Gegner an und wieder aus, Adrenalinrausch bei wenig Energie mit Schattenklingen, Mordlust, Verschwinden und Vorbereitung für Hinterhalt während Tiefe Einsicht, Schattenschritt, Entrinnen solo. Ihnen überlassen: Schurkenhandel und Rüstung schwächen (aufgeführt, aber deaktiviert), Finte und die Positionierung hinter dem Ziel für Hinterhalt.",
-- 44b84c55 English: Sinister Strike builder (Icy Veins)
[31] = "Finsterer Stoß als Aufbauangriff (Icy Veins)",
-- 610b2100 English: Off by default, and superseded for Phase 5. The Icy Veins, Warcraft Tavern,
--     Method and wowtbc.gg order from before the Siege of Orgrimmar patch: Slice and Dice,
--     Revealing Strike kept up, five-point Rupture on a long single-target fight and Eviscerate,
--     with Sinister Strike as the builder. Same reminders and pack play as the recommended Combat
--     premade. Choose it only if you follow those guides; enable it and disable the recommended
--     one.
[32] = "Standardmäßig deaktiviert und für Phase 5 überholt. Die Reihenfolge von Icy Veins, Warcraft Tavern, Method und wowtbc.gg aus der Zeit vor dem Patch zur Schlacht um Orgrimmar: Zerhäckseln, Enthüllender Stoß aufrechterhalten, Blutung mit fünf Punkten bei einem langen Einzelzielkampf und Ausweiden, mit Finsterer Stoß als Aufbauangriff. Dieselben Erinnerungen und dasselbe Spiel gegen Gruppen wie die empfohlene integrierte Kampf-Rotation. Wählen Sie sie nur, wenn Sie diesen Leitfäden folgen; aktivieren Sie sie und deaktivieren Sie die empfohlene.",
-- 972be132 English: Anticipation (Hekili)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue,
--     Mists of Pandaria Classic (variant key: Combat / Hekili). Names in parentheses (guide or tool
--     such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics, Warcraft Tavern)
--     are proper names and stay unchanged.
[33] = "Erwartung (Hekili)",
-- a677df00 English: Off by default. The Hekili MoP order for Combat with Anticipation: Revealing
--     Strike is the only builder, even under Bloodlust; finishers wait for Deep Insight, four
--     Anticipation charges or Shadow Blades coming back, then Slice and Dice, Rupture on one or two
--     long-lived targets, Crimson Tempest at seven enemies and Eviscerate; Slice and Dice is
--     refreshed early at 11 Bandit's Guile stacks; Fan of Knives from four enemies. It applies only
--     with Anticipation talented. Enable it and disable the recommended Combat premade to use it.
[34] = "Standardmäßig deaktiviert. Die MoP-Reihenfolge von Hekili für Kampf mit Erwartung: Enthüllender Stoß ist der einzige Aufbauangriff, selbst während Kampfrausch; Finisher warten auf Tiefe Einsicht, vier Aufladungen von Erwartung oder die Rückkehr von Schattenklingen, dann Zerhäckseln, Blutung auf einem oder zwei langlebigen Zielen, Blutroter Sturm bei sieben Gegnern und Ausweiden; Zerhäckseln wird bei 11 Stapeln Arglist des Banditen vorzeitig erneuert; Dolchfächer ab vier Gegnern. Sie gilt nur mit dem Talent Erwartung. Aktivieren Sie sie und deaktivieren Sie die empfohlene integrierte Kampf-Rotation, um sie zu verwenden.",
-- c2f73eb9 English: Recommended for Subtlety with Shadow Focus, from level 10 to 90 (simulator and
--     Wowhead for Phase 5). In Stealth or Shadow Dance: Premeditation, Slice and Dice before the
--     pull, finishers at five points, Ambush, Garrote. Outside: Slice and Dice; at five points
--     Slice and Dice and Rupture when they are about to drop, Eviscerate while both last; Marked
--     for Death; Hemorrhage to keep its bleed; Backstab (with a dagger) when the target is not
--     attacking you, otherwise Hemorrhage. Against three or more enemies: Slice and Dice, Crimson
--     Tempest, Eviscerate and Fan of Knives. Solo it adds Recuperate and Kidney Shot. Reminders:
--     poisons, Kick, Shadow Dance at 75 energy with Slice and Dice and Rupture up, Vanish when Find
--     Weakness is ending, Preparation, Shadow Blades outside Dance and Stealth, Shadowstep, Evasion
--     solo. Left to you: standing behind the target (RM cannot see facing), Tricks of the Trade and
--     Expose Armor (listed but off).
[35] = "Empfohlen für Täuschung mit Schattenfokus von Stufe 10 bis 90 (Simulation und Wowhead für Phase 5). In Verstohlenheit oder Schattentanz: Konzentration, Zerhäckseln vor dem Pull, Finisher bei fünf Punkten, Hinterhalt, Erdrosseln. Außerhalb: Zerhäckseln; bei fünf Punkten Zerhäckseln und Blutung, wenn sie bald auslaufen, Ausweiden, solange beide anhalten; Todesurteil; Blutsturz, um seine Blutung zu halten; Meucheln (mit einem Dolch), wenn das Ziel Sie nicht angreift, sonst Blutsturz. Gegen drei oder mehr Gegner: Zerhäckseln, Blutroter Sturm, Ausweiden und Dolchfächer. Solo kommen Gesundung und Nierenhieb hinzu. Erinnerungen: Gifte, Tritt, Schattentanz bei 75 Energie mit aktivem Zerhäckseln und aktiver Blutung, Verschwinden, wenn Schwächen aufspüren ausläuft, Vorbereitung, Schattenklingen außerhalb von Schattentanz und Verstohlenheit, Schattenschritt, Entrinnen solo. Ihnen überlassen: hinter dem Ziel zu stehen (RM kann die Blickrichtung nicht sehen), Schurkenhandel und Rüstung schwächen (aufgeführt, aber deaktiviert).",
-- a7cbb172 English: Subterfuge (Warcraft Tavern)
-- Context: Name of a Built In (premade) rotation, shown in the rotation list and picker: Rogue,
--     Mists of Pandaria Classic (variant key: Subtlety / WarcraftTavern). Names in parentheses
--     (guide or tool such as Icy Veins, Wowhead, SimulationCraft, simulator, Hekili, Mobalytics,
--     Warcraft Tavern) are proper names and stay unchanged.
[36] = "Trickbetrug (Warcraft Tavern)",
-- 01394d1f English: Chosen automatically instead of the Shadow Focus premade when your tier-1
--     talent is Subterfuge (Warcraft Tavern's build). Premeditation and Slice and Dice before the
--     pull; in Stealth, Shadow Dance or the Subterfuge linger, finishers at five points and then
--     Ambush as often as it lands. Two or three enemies: keep Rupture up and spend five points on
--     Crimson Tempest instead of Eviscerate; four or more add Fan of Knives. One target: Slice and
--     Dice, Rupture, Eviscerate, Hemorrhage for its bleed, Backstab from behind with a dagger, else
--     Hemorrhage. Shadow Dance and Vanish are reminders at 60 energy with Slice and Dice up; timing
--     them to trinket procs, as Tavern suggests, is up to you.
[37] = "Automatisch statt der integrierten Rotation mit Schattenfokus gewählt, wenn Ihr Talent der Stufe 1 Trickbetrug ist (der Build von Warcraft Tavern). Konzentration und Zerhäckseln vor dem Pull; in Verstohlenheit, Schattentanz oder der Nachwirkung von Trickbetrug Finisher bei fünf Punkten und dann Hinterhalt, so oft er trifft. Zwei oder drei Gegner: Blutung aufrechterhalten und fünf Punkte für Blutroter Sturm statt Ausweiden ausgeben; ab vier kommt Dolchfächer hinzu. Ein Ziel: Zerhäckseln, Blutung, Ausweiden, Blutsturz für seine Blutung, Meucheln von hinten mit einem Dolch, sonst Blutsturz. Schattentanz und Verschwinden sind Erinnerungen bei 60 Energie mit aktivem Zerhäckseln; sie auf Schmuck-Procs abzustimmen, wie Tavern empfiehlt, bleibt Ihnen überlassen.",
-- 60f6bea5 English: For levels 1 to 9, or a rogue who has not chosen a specialization yet; each
--     specialization's premade takes over once you pick one. Opens from Stealth with Cheap Shot
--     when solo, Ambush or Sinister Strike; suggests Stealth out of combat; Slice and Dice from two
--     points, Recuperate and Kidney Shot when solo and hurt, Eviscerate at four points (two when
--     the target is about to die), Sinister Strike. Reminders: poisons once learned, Kick, Evasion
--     solo.
[38] = "Für Stufe 1 bis 9 oder einen Schurken, der noch keine Spezialisierung gewählt hat; die integrierte Rotation jeder Spezialisierung übernimmt, sobald Sie eine wählen. Eröffnet aus der Verstohlenheit solo mit Fieser Trick, mit Hinterhalt oder Finsterer Stoß; schlägt außerhalb des Kampfes Verstohlenheit vor; Zerhäckseln ab zwei Punkten, Gesundung und Nierenhieb solo bei Verletzung, Ausweiden bei vier Punkten (zwei, wenn das Ziel kurz vor dem Tod steht), Finsterer Stoß. Erinnerungen: Gifte, sobald erlernt, Tritt, Entrinnen solo.",
}
